--- regression.test.mjs
+++ regression.test.mjs
@@ -0,0 +1,13 @@
+import { test } from 'node:test';
+import assert from 'node:assert/strict';
+import { slugify } from './src.mjs';
+
+test('empty input', () => assert.equal(slugify(''), ''));
+test('only separators', () => assert.equal(slugify(' -_!? '), ''));
+test('strips diacritics', () => assert.equal(slugify('Crème Brûlée'), 'creme-brulee'));
+test('compatibility decomposition', () => assert.equal(slugify('ﬁle ① ２'), 'file-1-2'));
+test('keeps non-Latin letters', () => assert.equal(slugify('Привет мир'), 'привет-мир'));
+test('keeps CJK and other numbers', () => assert.equal(slugify('東京 ٣'), '東京-٣'));
+test('marks produced by lowercasing are removed', () => assert.equal(slugify('İstanbul'), 'istanbul'));
+test('collapses runs and trims edges', () => assert.equal(slugify('--a  &&  b--'), 'a-b'));
+test('Devanagari marks removed, letters kept', () => assert.equal(slugify('हिन्दी'), 'हनद'));
